package com.myles.kotobafloat;
import android.app.*;import android.os.*;import android.view.accessibility.*;
/** 只给专用模拟器的输入验收使用。 / Text entry helper for the disposable emulator only. */
public final class Feature190Input extends Instrumentation {
    private String value;@Override public void onCreate(Bundle args){super.onCreate(args);value=args.getString("value","");start();}
    private AccessibilityNodeInfo editable(AccessibilityNodeInfo node){if(node==null)return null;if(node.isEditable())return node;for(int i=0;i<node.getChildCount();i++){AccessibilityNodeInfo found=editable(node.getChild(i));if(found!=null)return found;}return null;}
    @Override public void onStart(){Bundle result=new Bundle();try{UiAutomation automation=getUiAutomation();android.accessibilityservice.AccessibilityServiceInfo info=automation.getServiceInfo();info.flags|=android.accessibilityservice.AccessibilityServiceInfo.FLAG_RETRIEVE_INTERACTIVE_WINDOWS;automation.setServiceInfo(info);AccessibilityNodeInfo field=null;long deadline=SystemClock.elapsedRealtime()+10000;while(field==null&&SystemClock.elapsedRealtime()<deadline){field=editable(automation.getRootInActiveWindow());if(field==null)for(AccessibilityWindowInfo window:automation.getWindows()){field=editable(window.getRoot());if(field!=null)break;}if(field==null)SystemClock.sleep(100);}if(field==null)throw new AssertionError("No editable field after accessibility connection settled");Bundle args=new Bundle();args.putCharSequence(AccessibilityNodeInfo.ACTION_ARGUMENT_SET_TEXT_CHARSEQUENCE,value);if(!field.performAction(AccessibilityNodeInfo.ACTION_SET_TEXT,args))throw new AssertionError("Text input failed");result.putString("stream","PASS: Text entered\n");finish(Activity.RESULT_OK,result);}catch(Throwable error){result.putString("stream","FAIL: "+android.util.Log.getStackTraceString(error));finish(Activity.RESULT_CANCELED,result);}}
}
